import React, { useState } from 'react';
import { useApp } from '../context/AppContext';
import { getTheme } from '../utils/theme';
import { Icons } from '../utils/icons';

const DEMO_USERS = [
  { label: '🎓 Student', email: 'student@demo.com', color: '#6366f1' },
  { label: '👨‍🏫 Teacher', email: 'teacher@demo.com', color: '#10b981' },
  { label: '🛡 Admin', email: 'admin@demo.com', color: '#f59e0b' },
];

export default function Auth({ mode }) {
  const { setPage, login, register, dark } = useApp();
  const css = getTheme(dark);

  const [form, setForm] = useState({ name: '', email: '', password: '', role: 'student' });
  const [loading, setLoading] = useState(false);
  const [errors, setErrors] = useState({});

  const validate = () => {
    const e = {};
    if (mode === 'signup' && !form.name.trim()) e.name = 'Name is required';
    if (!form.email.trim()) e.email = 'Email is required';
    if (!form.password || form.password.length < 6) e.password = 'Min 6 characters';
    setErrors(e);
    return Object.keys(e).length === 0;
  };

  const handle = async () => {
    if (!validate()) return;
    setLoading(true);
    await new Promise((r) => setTimeout(r, 500));
    if (mode === 'login') login(form.email, form.password);
    else register(form);
    setLoading(false);
  };

  const handleKey = (e) => {
    if (e.key === 'Enter') handle();
  };

  return (
    <div
      style={{
        minHeight: '100vh',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        padding: 24,
        background: dark ? '#050810' : '#f8f9ff',
        position: 'relative',
        overflow: 'hidden',
      }}
    >
      {/* BG blobs */}
      <div
        style={{
          position: 'absolute',
          width: 500,
          height: 500,
          borderRadius: '50%',
          background: 'radial-gradient(circle,rgba(99,102,241,0.12) 0%,transparent 70%)',
          top: '-10%',
          right: '-10%',
          pointerEvents: 'none',
        }}
      />
      <div
        style={{
          position: 'absolute',
          width: 300,
          height: 300,
          borderRadius: '50%',
          background: 'radial-gradient(circle,rgba(139,92,246,0.1) 0%,transparent 70%)',
          bottom: '5%',
          left: '5%',
          pointerEvents: 'none',
        }}
      />

      <div style={{ width: '100%', maxWidth: 440, animation: 'scaleIn 0.35s ease' }}>
        {/* Header */}
        <div style={{ textAlign: 'center', marginBottom: 36 }}>
          <div
            style={{
              width: 56,
              height: 56,
              borderRadius: 16,
              background: 'linear-gradient(135deg,#6366f1,#8b5cf6)',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              fontSize: 28,
              margin: '0 auto 18px',
              boxShadow: '0 12px 32px rgba(99,102,241,0.35)',
            }}
          >
            ☕
          </div>
          <h1
            style={{
              fontSize: 30,
              fontWeight: 800,
              letterSpacing: '-1px',
              color: dark ? '#fff' : '#0f0f23',
              marginBottom: 8,
            }}
          >
            {mode === 'login' ? 'Welcome back' : 'Join Study Cafe'}
          </h1>
          <p style={{ color: dark ? '#64748b' : '#94a3b8', fontSize: 15 }}>
            {mode === 'login'
              ? 'Log in to continue your learning'
              : 'Start your academic journey today'}
          </p>
        </div>

        {/* Demo buttons (login only) */}
        {mode === 'login' && (
          <div style={{ marginBottom: 24 }}>
            <p
              style={{
                fontSize: 12,
                color: dark ? '#475569' : '#94a3b8',
                marginBottom: 10,
                textAlign: 'center',
                fontWeight: 500,
              }}
            >
              Quick demo access:
            </p>
            <div style={{ display: 'flex', gap: 8, justifyContent: 'center' }}>
              {DEMO_USERS.map((d) => (
                <button
                  key={d.label}
                  onClick={() => setForm((p) => ({ ...p, email: d.email, password: 'demo123' }))}
                  style={{
                    padding: '7px 14px',
                    borderRadius: 9,
                    border: `1px solid ${d.color}50`,
                    background: `${d.color}15`,
                    color: d.color,
                    fontSize: 12,
                    fontWeight: 700,
                    cursor: 'pointer',
                    transition: 'all 0.15s',
                  }}
                >
                  {d.label}
                </button>
              ))}
            </div>
          </div>
        )}

        {/* Form card */}
        <div style={{ ...css.card, padding: 32, borderRadius: 22 }}>
          {mode === 'signup' && (
            <Field label="Full Name" error={errors.name}>
              <input
                placeholder="e.g. Arjun Mehta"
                value={form.name}
                onChange={(e) => setForm((p) => ({ ...p, name: e.target.value }))}
                onKeyDown={handleKey}
                style={{
                  ...css.input,
                  borderColor: errors.name ? '#ef4444' : undefined,
                }}
              />
            </Field>
          )}

          <Field label="Email address" error={errors.email}>
            <input
              placeholder="you@college.edu"
              type="email"
              value={form.email}
              onChange={(e) => setForm((p) => ({ ...p, email: e.target.value }))}
              onKeyDown={handleKey}
              style={{
                ...css.input,
                borderColor: errors.email ? '#ef4444' : undefined,
              }}
            />
          </Field>

          <Field label="Password" error={errors.password}>
            <input
              placeholder="••••••••"
              type="password"
              value={form.password}
              onChange={(e) => setForm((p) => ({ ...p, password: e.target.value }))}
              onKeyDown={handleKey}
              style={{
                ...css.input,
                borderColor: errors.password ? '#ef4444' : undefined,
              }}
            />
          </Field>

          {mode === 'signup' && (
            <div style={{ marginBottom: 24 }}>
              <label style={css.label}>I am a...</label>
              <div style={{ display: 'flex', gap: 10 }}>
                {['student', 'teacher'].map((r) => (
                  <button
                    key={r}
                    onClick={() => setForm((p) => ({ ...p, role: r }))}
                    style={{
                      flex: 1,
                      padding: '12px',
                      borderRadius: 12,
                      border: `2px solid ${
                        form.role === r
                          ? '#6366f1'
                          : dark
                          ? 'rgba(255,255,255,0.08)'
                          : 'rgba(0,0,0,0.08)'
                      }`,
                      background:
                        form.role === r ? 'rgba(99,102,241,0.12)' : 'transparent',
                      color:
                        form.role === r ? '#818cf8' : dark ? '#64748b' : '#94a3b8',
                      fontSize: 14,
                      fontWeight: 700,
                      cursor: 'pointer',
                      transition: 'all 0.15s',
                      textTransform: 'capitalize',
                    }}
                  >
                    {r === 'student' ? '🎓 Student' : '👨‍🏫 Teacher'}
                  </button>
                ))}
              </div>
            </div>
          )}

          <button
            onClick={handle}
            disabled={loading}
            style={{
              ...css.btnPrimary,
              width: '100%',
              padding: '13px',
              fontSize: 15,
              borderRadius: 12,
              opacity: loading ? 0.7 : 1,
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              gap: 8,
            }}
          >
            {loading ? (
              <>
                <span style={{ animation: 'spin 1s linear infinite', display: 'inline-block' }}>⟳</span>
                Please wait...
              </>
            ) : mode === 'login' ? (
              'Log in →'
            ) : (
              'Create account →'
            )}
          </button>
        </div>

        {/* Footer links */}
        <p
          style={{
            textAlign: 'center',
            marginTop: 20,
            color: dark ? '#475569' : '#94a3b8',
            fontSize: 14,
          }}
        >
          {mode === 'login' ? "Don't have an account? " : 'Already have an account? '}
          <button
            onClick={() => setPage(mode === 'login' ? 'signup' : 'login')}
            style={{
              background: 'none',
              border: 'none',
              color: '#818cf8',
              cursor: 'pointer',
              fontWeight: 700,
              fontSize: 14,
              fontFamily: 'inherit',
            }}
          >
            {mode === 'login' ? 'Sign up free' : 'Log in'}
          </button>
        </p>

        <p style={{ textAlign: 'center', marginTop: 14 }}>
          <button
            onClick={() => setPage('landing')}
            style={{
              background: 'none',
              border: 'none',
              color: dark ? '#334155' : '#94a3b8',
              cursor: 'pointer',
              fontSize: 13,
              fontFamily: 'inherit',
            }}
          >
            ← Back to home
          </button>
        </p>
      </div>
    </div>
  );
}

function Field({ label, error, children }) {
  return (
    <div style={{ marginBottom: 16 }}>
      <label
        style={{
          display: 'block',
          fontSize: 13,
          fontWeight: 600,
          color: error ? '#ef4444' : '#94a3b8',
          marginBottom: 8,
        }}
      >
        {label}
      </label>
      {children}
      {error && (
        <p style={{ fontSize: 12, color: '#ef4444', marginTop: 5, fontWeight: 500 }}>{error}</p>
      )}
    </div>
  );
}
